#include <iostream>

int value = 100; // Global namespace scope, static storage duration

void testScopeAndLifetime() {
    static int callCount = 0; // Local static variable: retains value across calls
    int localVal = 5;         // Automatic storage duration: created and destroyed each call

    ++callCount;
    localVal += 2;

    std::cout << "Call " << callCount << ": localVal = " << localVal << "\n";
}

int main() {
    int value = 20; // Block scope: shadows global variable 'value'

    std::cout << "Local value: " << value << "\n";
    std::cout << "Global value via :: : " << ::value << "\n";

    testScopeAndLifetime();
    testScopeAndLifetime();
    testScopeAndLifetime();
    return 0;
}

#include <iostream>

// Inline utility using reference to double the value
inline void doubleInPlace(int& value) {
    value *= 2;
}

// Function template operating on any arithmetic type
template <typename T>
T calculateMax(T a, T b, T c = T{}) { // c has a default argument (zero-initialized)
    T maxVal = (a > b) ? a : b;
    return (maxVal > c) ? maxVal : c;
}

int main() {
    int x = 25;
    doubleInPlace(x);
    std::cout << "Doubled value: " << x << "\n";

    // Using template with integers and default argument
    std::cout << "Max of (12, 45): " << calculateMax(12, 45) << "\n";
    // Using template with three doubles
    std::cout << "Max of (3.14, 2.71, 9.81): " << calculateMax(3.14, 2.71, 9.81) << "\n";
    return 0;
}

#include <iostream>

// Recursive factorial using unsigned long long for large value support
unsigned long long factorialRecursive(unsigned int n) {
    if (n <= 1) { // Base case
        return 1;
    }
    return n * factorialRecursive(n - 1); // Recursive call
}

// Iterative factorial (efficient in memory and execution)
unsigned long long factorialIterative(unsigned int n) {
    unsigned long long result = 1;
    for (unsigned int i = 2; i <= n; ++i) {
        result *= i;
    }
    return result;
}

int main() {
    unsigned int num = 10;
    std::cout << "Factorial(" << num << ") Recursive: " << factorialRecursive(num) << "\n";
    std::cout << "Factorial(" << num << ") Iterative: " << factorialIterative(num) << "\n";
    return 0;
}
